/* @autogenerated */
import { Component, inject } from '@angular/core';
import { Snippet } from 'app/features/template/snippet/model/snippet.model';
import { SnippetRepository } from 'app/features/template/snippet/repository/snippet-repository.service';
import { ConfirmAction } from 'app/shared/toolkit/action/confirm-action';

@Component({ selector: 'snippet-view-delete-action', standalone: false, template: '' })
export class SnippetViewDeleteActionComponent extends ConfirmAction<Snippet> {
  readonly name = 'delete';
  protected readonly scope = 'template/snippet';
  protected readonly repository = inject(SnippetRepository);

  protected execute([item]: Snippet[]) {
    return this.repository.deleteByKey(item.uid);
  }
}
